void TianFenXI::ConfigureFaceSelectionBlock()
{
    if (selection0 == NULL)
    {
        return;
    }

    std::vector<NXOpen::Selection::MaskTriple> masks;
    NXOpen::Selection::MaskTriple faceMask;
    faceMask.Type = UF_solid_type;
    faceMask.Subtype = UF_solid_body_subtype;
    faceMask.SolidBodySubtype = UF_UI_SEL_FEATURE_ANY_FACE;
    masks.push_back(faceMask);

    NXOpen::Selection::MaskTriple edgeMask;
    edgeMask.Type = UF_solid_type;
    edgeMask.Subtype = UF_solid_body_subtype;
    edgeMask.SolidBodySubtype = UF_UI_SEL_FEATURE_ANY_EDGE;
    masks.push_back(edgeMask);

    selection0->SetSelectionFilter(NXOpen::Selection::SelectionActionClearAndEnableSpecific, masks);
    selection0->SetSelectModeAsString("Multiple");
    selection0->SetLabelString("选择面/排除边");
    selection0->SetCue("请选择基准面，可按 Shift 选边排除区域");
}

void TianFenXI::UpdateDeleteRVisibility()
{
    if (toggle0 == NULL || string01 == NULL)
    {
        return;
    }

    string01->SetShow(toggle0->Value());
}

void TianFenXI::LoadUiSettings()
{
    EnsureSettingsDirectory();

    if (toggle0 != NULL)
    {
        const int deleteR = GetPrivateProfileIntW(L"UI", L"DeleteR", toggle0->Value() ? 1 : 0, kSettingsPath);
        toggle0->SetValue(deleteR != 0);
    }

    if (string01 != NULL)
    {
        const std::string radiusText = ReadIniString(L"UI", L"DeleteRValue", L"5");
        if (!radiusText.empty())
        {
            string01->SetValue(radiusText.c_str());
        }
    }

    if (string0 != NULL)
    {
        const std::string gapText = ReadIniString(L"UI", L"GapValue", L"5");
        if (!gapText.empty())
        {
            string0->SetValue(gapText.c_str());
        }
    }

    DebugLog("UI settings loaded: deleteR=" +
        FormatTag(static_cast<tag_t>(toggle0 != NULL && toggle0->Value() ? 1 : 0)) +
        ", rValue=" + FormatDouble(ReadPositiveStringValue(string01, 5.0)) +
        ", gapValue=" + FormatDouble(ReadPositiveStringValue(string0, kDefaultGapDistance)));
}

void TianFenXI::SaveUiSettings()
{
    EnsureSettingsDirectory();

    WritePrivateProfileStringW(
        L"UI",
        L"DeleteR",
        (toggle0 != NULL && toggle0->Value()) ? L"1" : L"0",
        kSettingsPath);

    std::string radiusText = string01 != NULL ? string01->Value().GetText() : "5";
    int required = MultiByteToWideChar(CP_UTF8, 0, radiusText.c_str(), -1, NULL, 0);
    std::wstring radiusWide;
    if (required > 0)
    {
        radiusWide.assign(static_cast<std::size_t>(required - 1), L'\0');
        MultiByteToWideChar(CP_UTF8, 0, radiusText.c_str(), -1, &radiusWide[0], required);
    }
    if (radiusWide.empty())
    {
        radiusWide = L"5";
    }

    WritePrivateProfileStringW(L"UI", L"DeleteRValue", radiusWide.c_str(), kSettingsPath);
    std::string gapText = string0 != NULL ? string0->Value().GetText() : "5";
    required = MultiByteToWideChar(CP_UTF8, 0, gapText.c_str(), -1, NULL, 0);
    std::wstring gapWide;
    if (required > 0)
    {
        gapWide.assign(static_cast<std::size_t>(required - 1), L'\0');
        MultiByteToWideChar(CP_UTF8, 0, gapText.c_str(), -1, &gapWide[0], required);
    }
    if (gapWide.empty())
    {
        gapWide = L"5";
    }

    WritePrivateProfileStringW(L"UI", L"GapValue", gapWide.c_str(), kSettingsPath);
    DebugLog("UI settings saved: deleteR=" +
        FormatTag(static_cast<tag_t>(toggle0 != NULL && toggle0->Value() ? 1 : 0)) +
        ", rValue=" + radiusText +
        ", gapValue=" + gapText);
}

void TianFenXI::ClearPreviewHighlight(bool refresh)
{
    RestorePreviewFaceColors(previewColoredFaces, previewOriginalFaceColors);

    if (!highlightedGapFaces.empty())
    {
        DebugLog("Clear preview gap face highlight count=" +
            FormatTag(static_cast<tag_t>(highlightedGapFaces.size())));
    }
    for (std::size_t index = 0; index < highlightedGapFaces.size(); ++index)
    {
        if (highlightedGapFaces[index] != NULL_TAG)
        {
            UF_DISP_set_highlight(highlightedGapFaces[index], 0);
        }
    }

    if (!highlightedBoundaryEdges.empty())
    {
        DebugLog("Clear preview boundary edge highlight count=" +
            FormatTag(static_cast<tag_t>(highlightedBoundaryEdges.size())));
    }
    for (std::size_t index = 0; index < highlightedBoundaryEdges.size(); ++index)
    {
        if (highlightedBoundaryEdges[index] != NULL_TAG)
        {
            UF_DISP_set_highlight(highlightedBoundaryEdges[index], 0);
        }
    }
    highlightedBoundaryEdges.clear();
    highlightedGapFaces.clear();
    highlightedFaceChain.clear();
    skippedGapFaces.clear();
    hasPreviewThickness = false;
    previewThickness = 0.0;
    previewInwardNormal[0] = 0.0;
    previewInwardNormal[1] = 0.0;
    previewInwardNormal[2] = 0.0;

    if (refresh)
    {
        RefreshDisplay();
    }
}

void TianFenXI::PreviewSelectedFaceChain(bool createMiddlePlanes)
{
    DebugLog(std::string(createMiddlePlanes ? "Apply" : "Preview") + " selected face chain begin");
    ClearPreviewHighlight(false);

    if (selection0 == NULL)
    {
        DebugLog("Preview abort: selection0 is null");
        RefreshDisplay();
        return;
    }

    NXOpen::BlockStyler::PropertyList* properties = selection0->GetProperties();
    std::vector<NXOpen::TaggedObject*> selectedObjects = properties->GetTaggedObjectVector("SelectedObjects");
    delete properties;
    const std::vector<tag_t> selectedFaceTags = FindSelectedFaceTags(selectedObjects);
    if (!createMiddlePlanes && !autoSelectedGapFaces.empty())
    {
        RememberDeselectedAutoGapFaces(autoSelectedGapFaces, selectedFaceTags, userDeselectedGapFaces);
    }

    if (selectedObjects.empty())
    {
        DebugLog("Preview abort: no selected objects, keep user deselected gap faces for Shift box deselect");
        RefreshDisplay();
        return;
    }

    NXOpen::Face* selectedFace = FindBaseSelectedFace(
        selectedObjects,
        previewSelectedFaceTag,
        autoSelectedGapFaces);
    if (selectedFace == NULL)
    {
        DebugLog("Preview abort: no selected base face");
        RefreshDisplay();
        return;
    }

    tag_t selectedFaceTag = selectedFace->Tag();
    if (previewSelectedFaceTag != NULL_TAG && previewSelectedFaceTag != selectedFaceTag)
    {
        DebugLog("Preview base face changed: clear user deselected gap faces, old=" +
            FormatTag(previewSelectedFaceTag) +
            ", new=" + FormatTag(selectedFaceTag));
        userDeselectedGapFaces.clear();
    }
    previewSelectedFaceTag = selectedFaceTag;
    const std::vector<tag_t> selectedCurveTags = FindUserSelectedCurveTags(selectedObjects);
    const std::vector<tag_t> selectedAutoGapFaces = FindSelectedAutoGapFaces(selectedObjects, autoSelectedGapFaces);
    DebugLog("Preview selected face=" + FormatTag(selectedFaceTag) +
        ", selected curves=" + FormatTag(static_cast<tag_t>(selectedCurveTags.size())) +
        ", selected auto gap faces=" + FormatTag(static_cast<tag_t>(selectedAutoGapFaces.size())));
    tag_t bodyTag = NULL_TAG;
    if (UF_MODL_ask_face_body(selectedFaceTag, &bodyTag) != 0 || bodyTag == NULL_TAG)
    {
        DebugLog("Preview abort: cannot get face body, face=" + FormatTag(selectedFaceTag));
        RefreshDisplay();
        return;
    }
    DebugLog("Preview selected body=" + FormatTag(bodyTag));

    double selectedPoint[3] = {0.0, 0.0, 0.0};
    double selectedNormal[3] = {0.0, 0.0, 0.0};
    if (!AskPlanarFacePlane(selectedFaceTag, selectedPoint, selectedNormal))
    {
        DebugLog("Preview abort: selected face is not planar");
        RefreshDisplay();
        return;
    }
    DebugLog("Preview selected plane point=" + FormatVector3(selectedPoint) +
        ", normal=" + FormatVector3(selectedNormal));

    tag_t joinFaceFeatureTag = NULL_TAG;
    if (JoinBodyFacesOnSameSurface(bodyTag, joinFaceFeatureTag))
    {
        const tag_t joinedSelectedFaceTag =
            FindPlanarFaceNearReference(bodyTag, selectedPoint, selectedNormal);
        if (joinedSelectedFaceTag != NULL_TAG)
        {
            selectedFaceTag = joinedSelectedFaceTag;
            previewSelectedFaceTag = selectedFaceTag;
            if (!AskPlanarFacePlane(selectedFaceTag, selectedPoint, selectedNormal))
            {
                DebugLog("Preview abort: joined selected face is not planar");
                RefreshDisplay();
                return;
            }
            DebugLog("Preview selected face after join=" + FormatTag(selectedFaceTag) +
                ", point=" + FormatVector3(selectedPoint) +
                ", normal=" + FormatVector3(selectedNormal));
        }
    }

    double thickness = 0.0;
    double inwardNormal[3] = {0.0, 0.0, 0.0};
    if (!AskSheetThickness(bodyTag, selectedFaceTag, selectedPoint, selectedNormal, thickness, inwardNormal))
    {
        DebugLog("Preview fallback: thickness not found, build connected face chain without thickness exclusion");
        highlightedFaceChain = BuildSelectedFaceChain(bodyTag, selectedFaceTag, 0.0);
        if (highlightedFaceChain.size() <= 1)
        {
            DebugLog("Preview abort: connected face chain not found, no selected-face boundary fallback");
            RefreshDisplay();
            return;
        }

        const double gapDistance = ReadPositiveStringValue(string0, kDefaultGapDistance);
        const std::vector<GapEdgePair> gapEdgePairs = FindFaceChainGapEdgePairs(highlightedFaceChain, gapDistance);
        const std::vector<GapFaceGroup> gapFaceGroups =
            FindGapFaceGroupsFromGapEdgePairs(gapEdgePairs, thickness);
        highlightedBoundaryEdges = FlattenGapEdgePairs(gapEdgePairs);
        highlightedGapFaces = FlattenGapFaceGroups(gapFaceGroups);
        const std::set<std::size_t> skippedGroupIndexes = createMiddlePlanes ?
            FindSkippedGapGroupIndexesByUserDeselectedFaces(gapFaceGroups, userDeselectedGapFaces) :
            std::set<std::size_t>();
        skippedGapFaces = FlattenSkippedGapFaces(gapFaceGroups, skippedGroupIndexes);
        if (createMiddlePlanes)
        {
            const std::vector<GapFaceGroup> groupsToDelete =
                FilterGapGroupsDeselectedFaces(gapFaceGroups, userDeselectedGapFaces);
            DeleteGapGroupsWithMiddlePlanes(
                groupsToDelete,
                bodyTag,
                thickness,
                toggle0 != NULL && toggle0->Value(),
                ReadPositiveStringValue(string01, 5.0));
        }
        else
        {
            autoSelectedGapFaces = FilterUserDeselectedGapFaces(highlightedGapFaces, userDeselectedGapFaces);
            highlightedGapFaces = autoSelectedGapFaces;
            HighlightFaces(highlightedGapFaces);
            std::vector<NXOpen::TaggedObject*> rewriteObjects =
                BuildSelectionObjectsWithGapFaces(autoSelectedGapFaces);
            NXOpen::BlockStyler::PropertyList* rewriteProperties = selection0->GetProperties();
            try
            {
                updatingSelectionProgrammatically = true;
                rewriteProperties->SetTaggedObjectVector("SelectedObjects", rewriteObjects);
            }
            catch (...)
            {
                updatingSelectionProgrammatically = false;
                delete rewriteProperties;
                throw;
            }
            updatingSelectionProgrammatically = false;
            delete rewriteProperties;
        }
        DebugLog("Preview fallback face chain count=" +
            FormatTag(static_cast<tag_t>(highlightedFaceChain.size())) +
            ", gapPairs=" + FormatTag(static_cast<tag_t>(gapEdgePairs.size())) +
            ", gapFaceGroups=" + FormatTag(static_cast<tag_t>(gapFaceGroups.size())) +
            ", gapDistance=" + FormatDouble(gapDistance) +
            ", userDeselectedGapFaces=" + FormatTag(static_cast<tag_t>(userDeselectedGapFaces.size())) +
            ", skippedGapGroups=" + FormatTag(static_cast<tag_t>(skippedGroupIndexes.size())) +
            ", colored gap face count=" +
            FormatTag(static_cast<tag_t>(highlightedGapFaces.size())));
        RefreshDisplay();
        return;
    }
    hasPreviewThickness = true;
    previewThickness = thickness;
    previewInwardNormal[0] = inwardNormal[0];
    previewInwardNormal[1] = inwardNormal[1];
    previewInwardNormal[2] = inwardNormal[2];

    highlightedFaceChain = BuildSelectedFaceChain(bodyTag, selectedFaceTag, thickness);
    if (highlightedFaceChain.empty())
    {
        DebugLog("Preview abort: face chain empty, no selected-face boundary fallback");
        RefreshDisplay();
        return;
    }

    const double gapDistance = ReadPositiveStringValue(string0, kDefaultGapDistance);
    const std::vector<GapEdgePair> gapEdgePairs = FindFaceChainGapEdgePairs(highlightedFaceChain, gapDistance);
    const std::vector<GapFaceGroup> gapFaceGroups =
        FindGapFaceGroupsFromGapEdgePairs(gapEdgePairs, thickness);
    highlightedBoundaryEdges = FlattenGapEdgePairs(gapEdgePairs);
    highlightedGapFaces = FlattenGapFaceGroups(gapFaceGroups);
    const std::set<std::size_t> skippedGroupIndexes = createMiddlePlanes ?
        FindSkippedGapGroupIndexesByUserDeselectedFaces(gapFaceGroups, userDeselectedGapFaces) :
        std::set<std::size_t>();
    skippedGapFaces = FlattenSkippedGapFaces(gapFaceGroups, skippedGroupIndexes);
    if (createMiddlePlanes)
    {
        const std::vector<GapFaceGroup> groupsToDelete =
            FilterGapGroupsDeselectedFaces(gapFaceGroups, userDeselectedGapFaces);
        DeleteGapGroupsWithMiddlePlanes(
            groupsToDelete,
            bodyTag,
            thickness,
            toggle0 != NULL && toggle0->Value(),
            ReadPositiveStringValue(string01, 5.0));
    }
    else
    {
        autoSelectedGapFaces = FilterUserDeselectedGapFaces(highlightedGapFaces, userDeselectedGapFaces);
        highlightedGapFaces = autoSelectedGapFaces;
        HighlightFaces(highlightedGapFaces);
        std::vector<NXOpen::TaggedObject*> rewriteObjects =
            BuildSelectionObjectsWithGapFaces(autoSelectedGapFaces);
        NXOpen::BlockStyler::PropertyList* rewriteProperties = selection0->GetProperties();
        try
        {
            updatingSelectionProgrammatically = true;
            rewriteProperties->SetTaggedObjectVector("SelectedObjects", rewriteObjects);
        }
        catch (...)
        {
            updatingSelectionProgrammatically = false;
            delete rewriteProperties;
            throw;
        }
        updatingSelectionProgrammatically = false;
        delete rewriteProperties;
    }
    DebugLog("Preview face chain count=" + FormatTag(static_cast<tag_t>(highlightedFaceChain.size())) +
        ", gapPairs=" + FormatTag(static_cast<tag_t>(gapEdgePairs.size())) +
        ", gapFaceGroups=" + FormatTag(static_cast<tag_t>(gapFaceGroups.size())) +
        ", gapDistance=" + FormatDouble(gapDistance) +
        ", userDeselectedGapFaces=" + FormatTag(static_cast<tag_t>(userDeselectedGapFaces.size())) +
        ", skippedGapGroups=" + FormatTag(static_cast<tag_t>(skippedGroupIndexes.size())) +
        ", colored gap face count=" +
        FormatTag(static_cast<tag_t>(highlightedGapFaces.size())));
    RefreshDisplay();
}
